def backfill_overall_scores(apps, schema_editor):
    """Give runs judged before this table existed an overall score.

    The judge's own overall score, strengths, weaknesses and label were never saved, so
    they stay empty. The overall score is the average of the saved criterion scores,
    which is how the judge's own overall score is built.
    """
    Evaluation = apps.get_model('evaluations', 'Evaluation')
    ResponseEvaluation = apps.get_model('evaluations', 'ResponseEvaluation')

    scores = {}
    for response_id, score in Evaluation.objects.values_list('response_id', 'score'):
        scores.setdefault(response_id, []).append(score)

    for response_id, values in scores.items():
        average = (Decimal(sum(values)) / len(values)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        ResponseEvaluation.objects.get_or_create(
            response_id=response_id, defaults={'overall_score': average},
        )


